export function formatCents(cents: number): string {
	const sign = cents < 0 ? '-' : '';
	const abs = Math.abs(cents);
	const dollars = Math.floor(abs / 100);
	const rest = abs % 100;
	return sign + '$' + dollars + '.' + String(rest).padStart(2, '0');
}

/** Renders one line per item plus a total line, joined with newlines (see SPEC.md). */
export function formatReceipt(lines: Array<{ label: string; cents: number }>): string {
	let sum = 0;
	const out: string[] = [];
	for (const line of lines) {
		sum += line.cents;
		out.push(`${line.label}: ${formatCents(line.cents)}`);
	}
	out.push(`Total: ${formatCents(sum)}`);
	return out.join('\n');
}

